import {confirmInboundIdentity} from '../dist-test/identity-writer.mjs';
import {approveInboundRecovery} from '../dist-test/recovery-approval.mjs';
import {ingressFingerprint} from '../dist-test/authenticated-ingress.mjs';
import {recoverDeadInbound,recoveryPayloadHash} from '../dist-test/inbound-recovery.mjs';
import {applyHandoverJob} from '../dist-test/handover-control.mjs';
import {queueSafetyAlerts,claimSafetyAlert,failSafetyAlert} from '../dist-test/alert-delivery-queue.mjs';
import {scanSafetyHolds} from '../dist-test/safety-alerts.mjs';
import {processReceiptJob} from '../dist-test/receipt-processor.mjs';
import {normalizeInboundJob} from '../dist-test/normalized-inbound.mjs';
import {receiveSignedIngress} from '../dist-test/authenticated-ingress.mjs';
import {test,before,after} from 'node:test';
import assert from 'node:assert/strict';
import pg from 'pg';
import fs from 'node:fs/promises';
import {receiveInbound,claimInbound,completeInbound,failInbound,applyInboundEffects} from '../dist-test/inbound-jobs.mjs';
import {pauseConversation,resumeConversation,reserveDispatch,reserveDispatchBudgets,reserveDispatchFromPolicy,claimProviderStartFromPolicy,canBeginReservedAttempt,claimProviderStart,expireDispatches} from '../dist-test/messaging-safety.mjs';
import {settleProviderStart,reduceDeliveryReceipt,holdUnmatchedReceipts} from '../dist-test/delivery-receipts.mjs';
import {encryptTenantKey} from '../dist-test/tenant-crypto.mjs';
// Hard test target: synthetic loopback DB only. Never accepts DATABASE_URL.
const schema='safety_test_'+crypto.randomUUID().replaceAll('-','');
const admin=new pg.Pool({host:'127.0.0.1',port:55431,user:'sandbox',database:'postgres',max:1});
const pool=new pg.Pool({host:'127.0.0.1',port:55431,user:'sandbox',database:'postgres',max:20,options:'-c search_path='+schema});
const ws=()=>crypto.randomUUID(),scope=()=>({workspaceId:ws(),contactId:ws(),channelId:ws()}),actor=ws();
const q=(s,v)=>pool.query(s,v);
const valid=()=>({tenantMatches:true,credentialReady:true,permission:'allowed',approvalRequired:true,approved:true,lastInboundAt:Date.now()-1000,templateApproved:false,templateBound:false,now:Date.now()});
const budget=(n=5)=>({bucket:'hour',periodStart:new Date().toISOString().slice(0,13)+':00:00.000Z',limit:n});
async function active(s){await pauseConversation(pool,s,'initial');assert.equal(await resumeConversation(pool,s,actor,true),true);}
async function message(s,key=ws()){const id=ws();await q(`INSERT INTO cf_outbound_message(id,workspace_id,contact_id,channel_id,business_key,purpose,body,state,approved_by,approved_at) VALUES($1,$2,$3,$4,$5,'service','synthetic only','approved',$6,now())`,[id,s.workspaceId,s.contactId,s.channelId,key,actor]);return id;}
async function inbound(workspaceId,eventId=ws()){return receiveInbound(pool,{workspaceId,eventId,accountId:'synthetic',provider:'stub',payload:{synthetic:true},authenticated:true,tenantMapped:true});}
before(async()=>{await admin.query('CREATE SCHEMA '+schema);await q(`CREATE TABLE receptionist_contact(id uuid PRIMARY KEY,workspace_id uuid,opted_out boolean,needs_human boolean);CREATE TABLE cf_sessions(token_hash text PRIMARY KEY,user_id uuid,expires_at timestamptz);CREATE TABLE accounts_user(id uuid PRIMARY KEY,is_active boolean);CREATE TABLE organizations_organization(id uuid PRIMARY KEY,deleted_at timestamptz);CREATE TABLE workspaces_workspace(id uuid PRIMARY KEY,organization_id uuid,is_archived boolean);CREATE TABLE members_workspace_membership(id uuid PRIMARY KEY,user_id uuid,workspace_id uuid,workspace_role text,custom_role_id uuid);`);await q(await fs.readFile(new URL('../migrations/001_messaging_safety.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/002_global_suppression.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/003_effects_receipts.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/003b_unmatched_receipts.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/004_persisted_dispatch_policy.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/005_authenticated_ingress.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/006_normalized_inbound.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/007_receipt_channel.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/008_safety_alerts.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/009_alert_delivery_queue.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/010_handover_control.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/011_inbound_recovery.sql',import.meta.url),'utf8'));await q(await fs.readFile(new URL('../migrations/012_identity_mapping_audit.sql',import.meta.url),'utf8'));});
after(async()=>{await pool.end();await admin.query('DROP SCHEMA '+schema+' CASCADE');await admin.end();});
test('unauthenticated or unmapped event persists nothing',async()=>{for(const v of [{authenticated:false,tenantMapped:true},{authenticated:true,tenantMapped:false}])await assert.rejects(()=>receiveInbound(pool,{workspaceId:ws(),eventId:ws(),accountId:'a',provider:'stub',payload:{},...v}),/unauthenticated/);});
test('ten duplicate concurrent receipts preserve one durable identity',async()=>{const w=ws(),id=ws();const ids=await Promise.all(Array.from({length:10},()=>inbound(w,id)));assert.equal(new Set(ids).size,1);assert.equal(Number((await q('SELECT count(*) FROM cf_inbound_job WHERE workspace_id=$1',[w])).rows[0].count),1);});
test('same event ID is separate across tenants and accounts',async()=>{const id=ws(),w=ws();const a=await inbound(w,id),b=await inbound(ws(),id);assert.notEqual(a,b);const c=await receiveInbound(pool,{workspaceId:w,eventId:id,accountId:'other',provider:'stub',payload:{},authenticated:true,tenantMapped:true});assert.notEqual(a,c);});
test('duplicate receipt cannot overwrite original payload',async()=>{const w=ws(),id=ws(),a=await inbound(w,id);await receiveInbound(pool,{workspaceId:w,eventId:id,accountId:'synthetic',provider:'stub',payload:{changed:true},authenticated:true,tenantMapped:true});assert.deepEqual((await q('SELECT payload FROM cf_inbound_job WHERE id=$1',[a])).rows[0].payload,{synthetic:true});});
test('10 concurrent claims acquire a single job once',async()=>{const w=ws();await inbound(w);const r=await Promise.all(Array.from({length:10},()=>claimInbound(pool,w)));assert.equal(r.filter(Boolean).length,1);});
test('crash after receipt and after claim: lease recovery rejects stale completion',async()=>{const w=ws(),id=await inbound(w);const first=await claimInbound(pool,w);await q(`UPDATE cf_inbound_job SET lease_until=now()-interval '1 second' WHERE id=$1`,[id]);const second=await claimInbound(pool,w);assert.notEqual(first.lease_token,second.lease_token);assert.equal(second.attempts,2);assert.equal(await completeInbound(pool,w,id,first.lease_token),false);assert.equal(await completeInbound(pool,w,id,second.lease_token),true);assert.equal(await claimInbound(pool,w),null);});
test('wrong tenant cannot complete or fail claim',async()=>{const w=ws(),id=await inbound(w),j=await claimInbound(pool,w);assert.equal(await completeInbound(pool,ws(),id,j.lease_token),false);assert.equal(await failInbound(pool,ws(),id,j.lease_token,'provider_unavailable'),false);});
test('attempt exhaustion becomes dead letter, not dropped or endless retry',async()=>{const w=ws(),id=await inbound(w);await claimInbound(pool,w,1);await q(`UPDATE cf_inbound_job SET lease_until=now()-interval '1 second' WHERE id=$1`,[id]);assert.equal(await claimInbound(pool,w,1),null);assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[id])).rows[0].state,'dead');});
test('failed claim records safe code and backoff, current lease required',async()=>{const w=ws(),id=await inbound(w),j=await claimInbound(pool,w);await assert.rejects(()=>failInbound(pool,w,id,j.lease_token,'private customer text'),/invalid_error/);assert.equal(await failInbound(pool,w,id,j.lease_token,'provider_unavailable'),true);assert.equal(await claimInbound(pool,w),null);});
test('STOP before dispatch reservation prevents any reservation',async()=>{const s=scope();await active(s);const id=await message(s);await pauseConversation(pool,s,'stop',true);const r=await reserveDispatch(pool,s,id,valid(),budget());assert.equal(r.ok,false);assert.equal(r.reason,'globally_suppressed');assert.equal((await q('SELECT count(*) FROM cf_outbound_attempt WHERE message_id=$1',[id])).rows[0].count,'0');});
test('reservation before STOP is recorded; immediate recheck blocks, no recall claimed',async()=>{const s=scope();await active(s);const id=await message(s),r=await reserveDispatch(pool,s,id,valid(),budget());assert.equal(r.ok,true);assert.equal(await canBeginReservedAttempt(pool,s,id,r.attemptId),true);await pauseConversation(pool,s,'stop',true);assert.equal(await canBeginReservedAttempt(pool,s,id,r.attemptId),false);assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[id])).rows[0].state,'dispatching');});
test('20 competing reservations at cap1 authorize only one',async()=>{const s=scope();await active(s);const ids=await Promise.all(Array.from({length:20},()=>message(s)));const r=await Promise.all(ids.map(id=>reserveDispatch(pool,s,id,valid(),budget(1))));assert.equal(r.filter(x=>x.ok).length,1);assert.equal((await q('SELECT reserved FROM cf_send_budget WHERE workspace_id=$1',[s.workspaceId])).rows[0].reserved,1);});
test('same outbox message cannot be claimed twice',async()=>{const s=scope();await active(s);const id=await message(s);const r=await Promise.all(Array.from({length:10},()=>reserveDispatch(pool,s,id,valid(),budget())));assert.equal(r.filter(x=>x.ok).length,1);});
test('wrong tenant/contact cannot reserve an outbound message',async()=>{const s=scope();await active(s);const id=await message(s),other=scope();await active(other);assert.equal((await reserveDispatch(pool,other,id,valid(),budget())).ok,false);});
test('missing control fails closed; authorized resume does not invent it',async()=>{const s=scope();assert.equal(await resumeConversation(pool,s,actor,true),false);await assert.rejects(()=>resumeConversation(pool,s,actor,false),/forbidden/);});
test('STOP suppression survives explicit resume attempt',async()=>{const s=scope();await pauseConversation(pool,s,'stop',true);assert.equal(await resumeConversation(pool,s,actor,true),false);assert.equal((await q('SELECT suppressed FROM cf_conversation_control WHERE workspace_id=$1',[s.workspaceId])).rows[0].suppressed,true);});
test('crash after reservation becomes unknown and cannot be blindly re-reserved',async()=>{const s=scope();await active(s);const id=await message(s),r=await reserveDispatch(pool,s,id,valid(),budget());await q(`UPDATE cf_outbound_message SET lease_until=now()-interval '1 second' WHERE id=$1`,[id]);assert.equal(await canBeginReservedAttempt(pool,s,id,r.attemptId),false);assert.equal(await expireDispatches(pool,s.workspaceId),1);assert.equal((await reserveDispatch(pool,s,id,valid(),budget())).ok,false);assert.equal((await q('SELECT result FROM cf_outbound_attempt WHERE id=$1',[r.attemptId])).rows[0].result,'unknown');});
test('pause/resume audit persists actor and control version',async()=>{const s=scope();await active(s);const r=await q('SELECT action,actor_id,version FROM cf_control_audit WHERE workspace_id=$1 ORDER BY version',[s.workspaceId]);assert.equal(r.rows.length,2);assert.equal(r.rows[1].action,'resume');assert.equal(r.rows[1].actor_id,actor);});

test('two competing provider starts consume one exclusive start fence',async()=>{const s=scope();await active(s);const id=await message(s),r=await reserveDispatch(pool,s,id,valid(),budget());const claims=await Promise.all(Array.from({length:10},()=>claimProviderStart(pool,s,id,r.attemptId)));assert.equal(claims.filter(Boolean).length,1);assert.equal((await q('SELECT start_token FROM cf_outbound_message WHERE id=$1',[id])).rows[0].start_token,claims.find(Boolean));});
test('STOP before consuming start claim blocks it',async()=>{const s=scope();await active(s);const id=await message(s),r=await reserveDispatch(pool,s,id,valid(),budget());await pauseConversation(pool,s,'stop',true);assert.equal(await claimProviderStart(pool,s,id,r.attemptId),null);});
test('crash after consuming start cannot start again; expiry becomes unknown',async()=>{const s=scope();await active(s);const id=await message(s),r=await reserveDispatch(pool,s,id,valid(),budget());assert.ok(await claimProviderStart(pool,s,id,r.attemptId));assert.equal(await claimProviderStart(pool,s,id,r.attemptId),null);await q(`UPDATE cf_outbound_message SET lease_until=now()-interval '1 second' WHERE id=$1`,[id]);assert.equal(await expireDispatches(pool,s.workspaceId),1);assert.equal(await claimProviderStart(pool,s,id,r.attemptId),null);});
test('exhausted lower limit persists even when reservation fails',async()=>{const s=scope();await active(s);assert.equal((await reserveDispatch(pool,s,await message(s),valid(),budget(5))).ok,true);assert.equal((await reserveDispatch(pool,s,await message(s),valid(),budget(1))).ok,false);assert.equal((await reserveDispatch(pool,s,await message(s),valid(),budget(5))).ok,false);assert.equal((await q('SELECT limit_count FROM cf_send_budget WHERE workspace_id=$1',[s.workspaceId])).rows[0].limit_count,1);});
test('concurrent low-limit calls cannot be widened by stale high limits',async()=>{const s=scope();await active(s);const first=await message(s);assert.equal((await reserveDispatch(pool,s,first,valid(),budget(5))).ok,true);await reserveDispatch(pool,s,await message(s),valid(),budget(1));const ids=await Promise.all(Array.from({length:10},()=>message(s)));const rs=await Promise.all(ids.map(id=>reserveDispatch(pool,s,id,valid(),budget(5))));assert.equal(rs.filter(x=>x.ok).length,0);});

test('STOP on one channel blocks every channel for that tenant contact',async()=>{const a=scope(),b={...a,channelId:ws()};await active(a);await active(b);const id=await message(b);await pauseConversation(pool,a,'stop',true);assert.equal((await reserveDispatch(pool,b,id,valid(),budget())).reason,'globally_suppressed');assert.equal(await resumeConversation(pool,b,actor,true),false);});
test('global suppression blocks reserved second-channel start',async()=>{const a=scope(),b={...a,channelId:ws()};await active(a);await active(b);const id=await message(b),r=await reserveDispatch(pool,b,id,valid(),budget());await pauseConversation(pool,a,'stop',true);assert.equal(await claimProviderStart(pool,b,id,r.attemptId),null);assert.equal(await canBeginReservedAttempt(pool,b,id,r.attemptId),false);});
test('one exhausted bucket never partially charges another',async()=>{const s=scope();await active(s);const id=await message(s),bs=[{...budget(5),bucket:'hour'},{...budget(0),bucket:'day'}];assert.equal((await reserveDispatchBudgets(pool,s,id,valid(),bs)).ok,false);assert.equal((await q('SELECT sum(reserved) FROM cf_send_budget WHERE workspace_id=$1',[s.workspaceId])).rows[0].sum,'0');});
test('concurrent multi-bucket reservations obey tightest cap despite input order',async()=>{const s=scope();await active(s);const bs=[{...budget(7),bucket:'hour'},{...budget(3),bucket:'day'},{...budget(10),bucket:'month'}],ids=await Promise.all(Array.from({length:20},()=>message(s)));const r=await Promise.all(ids.map((id,i)=>reserveDispatchBudgets(pool,s,id,valid(),i%2?bs:[...bs].reverse())));assert.equal(r.filter(x=>x.ok).length,3);const rows=(await q('SELECT reserved FROM cf_send_budget WHERE workspace_id=$1',[s.workspaceId])).rows;assert.deepEqual(rows.map(x=>x.reserved),[3,3,3]);});
test('duplicate budget canonical time identities fail closed',async()=>{const s=scope();await active(s);const b=budget();assert.equal((await reserveDispatchBudgets(pool,s,await message(s),valid(),[b,{...b,periodStart:b.periodStart.replace('.000Z','+00:00')}])).reason,'duplicate_budget');});

async function effect(c,w,id,key){return c.query(`INSERT INTO cf_inbound_effect(workspace_id,job_id,effect_key,result) VALUES($1,$2,$3,'{"synthetic":true}') ON CONFLICT DO NOTHING`,[w,id,key]);}
test('effects and completion commit once despite concurrent stale runner',async()=>{const w=ws(),id=await inbound(w),j=await claimInbound(pool,w);const r=await Promise.all(Array.from({length:5},()=>applyInboundEffects(pool,w,id,j.lease_token,c=>effect(c,w,id,'lead'))));assert.equal(r.filter(Boolean).length,1);assert.equal((await q('SELECT count(*) FROM cf_inbound_effect WHERE job_id=$1',[id])).rows[0].count,'1');});
test('failed effect callback rolls back records and leaves recoverable job',async()=>{const w=ws(),id=await inbound(w),j=await claimInbound(pool,w);await assert.rejects(()=>applyInboundEffects(pool,w,id,j.lease_token,async c=>{await effect(c,w,id,'lead');throw Error('synthetic failure')}));assert.equal((await q('SELECT count(*) FROM cf_inbound_effect WHERE job_id=$1',[id])).rows[0].count,'0');assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[id])).rows[0].state,'processing');});
test('lease expired during effects rolls back instead of committing stale effects',async()=>{const w=ws(),id=await inbound(w),j=await claimInbound(pool,w);const ok=await applyInboundEffects(pool,w,id,j.lease_token,async c=>{await effect(c,w,id,'lead');await c.query(`UPDATE cf_inbound_job SET lease_until=clock_timestamp()-interval '1 second' WHERE id=$1`,[id]);});assert.equal(ok,false);assert.equal((await q('SELECT count(*) FROM cf_inbound_effect WHERE job_id=$1',[id])).rows[0].count,'0');});
async function started(){const s=scope();await active(s);const id=await message(s);await q(`UPDATE cf_outbound_message SET provider='stub',account_id='account1' WHERE id=$1`,[id]);const r=await reserveDispatch(pool,s,id,valid(),budget());const token=await claimProviderStart(pool,s,id,r.attemptId);return{s,id,r,token,input:{workspaceId:s.workspaceId,messageId:id,attemptId:r.attemptId,startToken:token,provider:'stub',accountId:'account1',outcome:'accepted',providerMessageId:ws()}};}
test('accepted settlement requires exact start owner, tenant, account and provider ID',async()=>{const x=await started();for(const change of [{startToken:ws()},{workspaceId:ws()},{accountId:'wrong'},{providerMessageId:''}])assert.equal(await settleProviderStart(pool,{...x.input,...change}),false);assert.equal(await settleProviderStart(pool,x.input),true);assert.equal(await settleProviderStart(pool,x.input),false);});
const receipt=x=>({channelId:x.s.channelId,workspaceId:x.s.workspaceId,provider:'stub',accountId:'account1',eventId:ws(),providerMessageId:x.input.providerMessageId,kind:'delivered',authenticated:true,tenantMapped:true});
test('forged/mismapped/wrong tenant receipt makes no state effect',async()=>{const x=await started();await settleProviderStart(pool,x.input);for(const change of [{authenticated:false},{tenantMapped:false},{workspaceId:ws()},{accountId:'wrong'},{provider:'wrong'}])assert.equal(await reduceDeliveryReceipt(pool,{...receipt(x),...change}),change.authenticated===false||change.tenantMapped===false?'invalid':'retryable_unmatched');assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'provider_accepted');});
test('receipt reducer is duplicate safe and monotonic under out-of-order delivery',async()=>{const x=await started();await settleProviderStart(pool,x.input);const read={...receipt(x),kind:'read'};assert.equal(await reduceDeliveryReceipt(pool,read),'reconciled');assert.equal(await reduceDeliveryReceipt(pool,read),'duplicate');await reduceDeliveryReceipt(pool,receipt(x));await reduceDeliveryReceipt(pool,{...receipt(x),kind:'failed'});assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'read');});
test('unknown timeout has no blind resend and late exact response can reconcile',async()=>{const x=await started();assert.equal(await settleProviderStart(pool,{...x.input,outcome:'unknown'}),true);assert.equal(await claimProviderStart(pool,x.s,x.id,x.r.attemptId),null);assert.equal(await settleProviderStart(pool,x.input),true);await reduceDeliveryReceipt(pool,receipt(x));assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'delivered');});
test('cancelled message does not resurrect from a valid receipt',async()=>{const x=await started();await settleProviderStart(pool,x.input);await q(`UPDATE cf_outbound_message SET state='cancelled' WHERE id=$1`,[x.id]);await reduceDeliveryReceipt(pool,receipt(x));assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'cancelled');});

test('early receipt persists and reconciles after accepted response',async()=>{const x=await started(),r=receipt(x);assert.equal(await reduceDeliveryReceipt(pool,r),'retryable_unmatched');assert.equal(await reduceDeliveryReceipt(pool,r),'retryable_unmatched');assert.equal((await q('SELECT count(*) FROM cf_unmatched_receipt WHERE workspace_id=$1',[x.s.workspaceId])).rows[0].count,'1');assert.equal(await settleProviderStart(pool,x.input),true);assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'delivered');assert.equal(await reduceDeliveryReceipt(pool,r),'duplicate');});
test('early read and delivery reconcile once after unknown/lost response, monotonic',async()=>{const x=await started();await reduceDeliveryReceipt(pool,{...receipt(x),kind:'read'});await reduceDeliveryReceipt(pool,receipt(x));await settleProviderStart(pool,{...x.input,outcome:'unknown'});assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'unknown');await settleProviderStart(pool,x.input);assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'read');assert.equal((await q(`SELECT count(*) FROM cf_unmatched_receipt WHERE workspace_id=$1 AND state<>'reconciled'`,[x.s.workspaceId])).rows[0].count,'0');});
test('receipt racing accepted response cannot be lost',async()=>{const x=await started();await Promise.all([reduceDeliveryReceipt(pool,receipt(x)),settleProviderStart(pool,x.input)]);assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'delivered');});
test('unresolved receipt ages to held without inventing a send binding',async()=>{const x=await started();await reduceDeliveryReceipt(pool,receipt(x));await q(`UPDATE cf_unmatched_receipt SET created_at=now()-interval '10 minutes' WHERE workspace_id=$1`,[x.s.workspaceId]);assert.equal(await holdUnmatchedReceipts(pool,x.s.workspaceId),1);assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'dispatching');await settleProviderStart(pool,x.input);assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'delivered');});

const cryptoEnv={DJANGO_SECRET_KEY:'synthetic-crypto-only',ENCRYPTION_KEY_SALT:'synthetic-salt'};
async function policyFixture(){const s=scope();await active(s);const id=await message(s);const key=await encryptTenantKey('synthetic-provider-secret',cryptoEnv);await q(`INSERT INTO cf_workspace_dispatch_policy(workspace_id,enabled,plan_active,hour_limit,day_limit,month_limit,evidence_ref,valid_until) VALUES($1,true,true,5,10,20,'synthetic-approved-config',now()+interval '1 day')`,[s.workspaceId]);await q(`INSERT INTO cf_channel_dispatch_binding(workspace_id,channel_id,provider,account_id,status,api_key,evidence_ref,valid_until) VALUES($1,$2,'stub','account1','connected',$3,'synthetic-verified-binding',now()+interval '1 day')`,[s.workspaceId,s.channelId,key]);await q(`INSERT INTO cf_contact_permission(workspace_id,contact_id,channel_id,purpose,status,evidence_ref,valid_until) VALUES($1,$2,$3,'service','allowed','synthetic-explicit-permission',now()+interval '1 day')`,[s.workspaceId,s.contactId,s.channelId]);const body='synthetic only',hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(body)))].map(x=>x.toString(16).padStart(2,'0')).join('');await q(`UPDATE cf_outbound_message SET provider='stub',account_id='account1',approved_body_sha256=$2 WHERE id=$1`,[id,hash]);await q(`UPDATE cf_conversation_control SET last_inbound_at=now()-interval '1 minute',inbound_evidence_ref='synthetic-signed-inbound' WHERE workspace_id=$1`,[s.workspaceId]);return{s,id};}
test('persisted policy derives all three server buckets and exclusive start',async()=>{const {s,id}=await policyFixture(),r=await reserveDispatchFromPolicy(pool,s,id,cryptoEnv);assert.equal(r.ok,true);const bs=(await q('SELECT bucket,reserved FROM cf_send_budget WHERE workspace_id=$1 ORDER BY bucket',[s.workspaceId])).rows;assert.deepEqual(bs.map(x=>x.bucket),['day','hour','month']);assert.ok(bs.every(x=>x.reserved===1));assert.equal(await claimProviderStart(pool,s,id,r.attemptId),null);assert.ok(await claimProviderStartFromPolicy(pool,s,id,r.attemptId,cryptoEnv));assert.equal(await claimProviderStartFromPolicy(pool,s,id,r.attemptId,cryptoEnv),null);});
test('caller booleans cannot bypass a persisted workspace policy',async()=>{const {s,id}=await policyFixture();await q('UPDATE cf_workspace_dispatch_policy SET enabled=false WHERE workspace_id=$1',[s.workspaceId]);assert.equal((await reserveDispatch(pool,s,id,valid(),budget(999))).reason,'persisted_policy_required');assert.equal((await reserveDispatchFromPolicy(pool,s,id,cryptoEnv)).reason,'policy_unavailable');});
for(const [label,sql,reason] of [['withdrawn permission',`UPDATE cf_contact_permission SET withdrawn_at=now() WHERE workspace_id=$1`,'permission_missing'],['expired evidence',`UPDATE cf_channel_dispatch_binding SET valid_until=now()-interval '1 second' WHERE workspace_id=$1`,'binding_unavailable'],['revoked account',`UPDATE cf_channel_dispatch_binding SET status='revoked' WHERE workspace_id=$1`,'binding_unavailable'],['body changed after approval',`UPDATE cf_outbound_message SET body='different' WHERE workspace_id=$1`,'approval_content_mismatch'],['wrong account',`UPDATE cf_outbound_message SET account_id='other' WHERE workspace_id=$1`,'binding_unavailable'],['missing inbound proof',`UPDATE cf_conversation_control SET inbound_evidence_ref=NULL WHERE workspace_id=$1`,'template_required']])test('persisted policy fails closed: '+label,async()=>{const {s,id}=await policyFixture();await q(sql,[s.workspaceId]);assert.equal((await reserveDispatchFromPolicy(pool,s,id,cryptoEnv)).reason,reason);});
test('policy revoked after reservation blocks consuming start',async()=>{const {s,id}=await policyFixture(),r=await reserveDispatchFromPolicy(pool,s,id,cryptoEnv);await q('UPDATE cf_workspace_dispatch_policy SET enabled=false,version=version+1 WHERE workspace_id=$1',[s.workspaceId]);assert.equal(await claimProviderStartFromPolicy(pool,s,id,r.attemptId,cryptoEnv),null);});
test('credential rotation after reservation blocks consuming start',async()=>{const {s,id}=await policyFixture(),r=await reserveDispatchFromPolicy(pool,s,id,cryptoEnv);await q('UPDATE cf_channel_dispatch_binding SET version=version+1 WHERE workspace_id=$1',[s.workspaceId]);assert.equal(await claimProviderStartFromPolicy(pool,s,id,r.attemptId,cryptoEnv),null);});
test('purpose-specific approved template required outside service window',async()=>{const {s,id}=await policyFixture();await q(`UPDATE cf_conversation_control SET last_inbound_at=now()-interval '25 hours' WHERE workspace_id=$1`,[s.workspaceId]);assert.equal((await reserveDispatchFromPolicy(pool,s,id,cryptoEnv)).reason,'template_required');await q(`UPDATE cf_outbound_message SET template_id='t1',template_version='v1',template_language='en' WHERE id=$1`,[id]);await q(`INSERT INTO cf_template_dispatch_policy(workspace_id,channel_id,account_id,template_id,version,language,purpose,status,evidence_ref,valid_until) VALUES($1,$2,'account1','t1','v1','en','service','approved','synthetic-template-proof',now()+interval '1 day')`,[s.workspaceId,s.channelId]);assert.equal((await reserveDispatchFromPolicy(pool,s,id,cryptoEnv)).ok,true);});

test('cap changed without version bump still invalidates persisted reservation',async()=>{const {s,id}=await policyFixture(),r=await reserveDispatchFromPolicy(pool,s,id,cryptoEnv);await q('UPDATE cf_workspace_dispatch_policy SET hour_limit=0 WHERE workspace_id=$1',[s.workspaceId]);assert.equal(await claimProviderStartFromPolicy(pool,s,id,r.attemptId,cryptoEnv),null);});
test('permission changed after reservation blocks consuming start',async()=>{const {s,id}=await policyFixture(),r=await reserveDispatchFromPolicy(pool,s,id,cryptoEnv);await q(`UPDATE cf_contact_permission SET status='denied' WHERE workspace_id=$1`,[s.workspaceId]);assert.equal(await claimProviderStartFromPolicy(pool,s,id,r.attemptId,cryptoEnv),null);});
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
test('consuming start cannot outlive lease while waiting on global lock',async()=>{const s=scope();await active(s);const id=await message(s),r=await reserveDispatch(pool,s,id,valid(),budget());await q(`UPDATE cf_outbound_message SET lease_until=clock_timestamp()+interval '150 milliseconds' WHERE id=$1`,[id]);const lock=await pool.connect();await lock.query('BEGIN');await lock.query('SELECT 1 FROM cf_contact_suppression WHERE workspace_id=$1 AND contact_id=$2 FOR UPDATE',[s.workspaceId,s.contactId]);const start=claimProviderStart(pool,s,id,r.attemptId);await delay(275);await lock.query('COMMIT');lock.release();assert.equal(await start,null);});
for(const bucket of ['hour','day','month'])test('consuming start fails closed after '+bucket+' period rollover',async()=>{const {s,id}=await policyFixture(),r=await reserveDispatchFromPolicy(pool,s,id,cryptoEnv);const old=(await q(`SELECT period_start-interval '1 ${bucket}' AS old FROM cf_budget_reservation WHERE attempt_id=$1 AND bucket=$2`,[r.attemptId,bucket])).rows[0].old;await q(`INSERT INTO cf_send_budget(workspace_id,bucket,period_start,reserved,limit_count) VALUES($1,$2,$3,1,20)`,[s.workspaceId,bucket,old]);await q(`UPDATE cf_budget_reservation SET period_start=$3 WHERE attempt_id=$1 AND bucket=$2`,[r.attemptId,bucket,old]);assert.equal(await claimProviderStartFromPolicy(pool,s,id,r.attemptId,cryptoEnv),null);});
test('evidence expiring during policy lock wait is rechecked at wall clock',async()=>{const {s,id}=await policyFixture();await q(`UPDATE cf_contact_permission SET valid_until=clock_timestamp()+interval '200 milliseconds' WHERE workspace_id=$1`,[s.workspaceId]);const r=await reserveDispatchFromPolicy(pool,s,id,cryptoEnv);assert.equal(r.ok,true);const lock=await pool.connect();await lock.query('BEGIN');await lock.query('SELECT 1 FROM cf_channel_dispatch_binding WHERE workspace_id=$1 FOR UPDATE',[s.workspaceId]);const start=claimProviderStartFromPolicy(pool,s,id,r.attemptId,cryptoEnv);await delay(300);await lock.query('COMMIT');lock.release();assert.equal(await start,null);});
test('service window closing during row wait blocks final consuming start',async()=>{const {s,id}=await policyFixture();await q(`UPDATE cf_conversation_control SET last_inbound_at=clock_timestamp()-interval '24 hours'+interval '200 milliseconds' WHERE workspace_id=$1`,[s.workspaceId]);const r=await reserveDispatchFromPolicy(pool,s,id,cryptoEnv);assert.equal(r.ok,true);const lock=await pool.connect();await lock.query('BEGIN');await lock.query('SELECT 1 FROM cf_channel_dispatch_binding WHERE workspace_id=$1 FOR UPDATE',[s.workspaceId]);const start=claimProviderStartFromPolicy(pool,s,id,r.attemptId,cryptoEnv);await delay(300);await lock.query('COMMIT');lock.release();assert.equal(await start,null);});
async function signedFixture(){const endpointId=ws(),workspaceId=ws(),channelId=ws(),secret='synthetic-endpoint-secret',accountId=ws(),profileId=ws();await q(`INSERT INTO cf_webhook_ingress_binding(endpoint_id,workspace_id,channel_id,provider,account_id,profile_id,encrypted_secret,enabled,evidence_ref,valid_until) VALUES($1,$2,$3,'zernio',$4,$5,$6,true,'SYNTHETIC',clock_timestamp()+interval '1 hour')`,[endpointId,workspaceId,channelId,accountId,profileId,await encryptTenantKey(secret,cryptoEnv)]);const event={id:ws(),event:'message.received',account:{accountId,profileId},message:{id:ws(),conversationId:ws(),direction:'incoming',text:'SYNTHETIC ONLY'},timestamp:new Date().toISOString()};return{endpointId,workspaceId,channelId,secret,event};}
async function signedInput(f,event=f.event){const raw=new TextEncoder().encode(JSON.stringify(event)),key=await crypto.subtle.importKey('raw',new TextEncoder().encode(f.secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);const signature=Buffer.from(await crypto.subtle.sign('HMAC',key,raw)).toString('hex');return{endpointId:f.endpointId,raw,signature,eventHeader:event.event,eventIdHeader:event.id};}
test('signed ingress derives tenant and channel only from persisted binding',async()=>{const f=await signedFixture();f.event.workspaceId=ws();f.event.authenticated=true;const r=await receiveSignedIngress(pool,await signedInput(f),cryptoEnv);assert.equal(r.workspaceId,f.workspaceId);assert.equal(r.channelId,f.channelId);assert.equal((await q('SELECT workspace_id FROM cf_inbound_job WHERE id=$1',[r.jobId])).rows[0].workspace_id,f.workspaceId);});
test('signed ingress duplicate concurrent events enqueue one durable job',async()=>{const f=await signedFixture(),input=await signedInput(f);const r=await Promise.all(Array.from({length:10},()=>receiveSignedIngress(pool,input,cryptoEnv)));assert.equal(new Set(r.map(x=>x.jobId)).size,1);});
test('signed ingress tampered bytes and forged signature persist nothing',async()=>{const f=await signedFixture(),input=await signedInput(f);for(const change of [{raw:new TextEncoder().encode('{}')},{signature:'0'.repeat(64)},{signature:input.signature.toUpperCase()},{signature:''}])assert.equal(await receiveSignedIngress(pool,{...input,...change},cryptoEnv),null);assert.equal((await q('SELECT count(*) FROM cf_inbound_job WHERE workspace_id=$1',[f.workspaceId])).rows[0].count,'0');});
test('signed ingress rejects account profile event id and event header mismatch',async()=>{const f=await signedFixture();for(const event of [{...f.event,account:{...f.event.account,accountId:ws()}},{...f.event,account:{...f.event.account,profileId:ws()}},{...f.event,account:{...f.event.account,id:ws()}}])assert.equal(await receiveSignedIngress(pool,await signedInput(f,event),cryptoEnv),null);const i=await signedInput(f);for(const change of [{eventIdHeader:ws()},{eventHeader:'message.read'}])assert.equal(await receiveSignedIngress(pool,{...i,...change},cryptoEnv),null);});
test('signed ingress disabled expired absent and wrong-key bindings fail closed',async()=>{const f=await signedFixture(),input=await signedInput(f);assert.equal(await receiveSignedIngress(pool,{...input,endpointId:ws()},cryptoEnv),null);assert.equal(await receiveSignedIngress(pool,input,{DJANGO_SECRET_KEY:'wrong',ENCRYPTION_KEY_SALT:'wrong'}),null);await q('UPDATE cf_webhook_ingress_binding SET enabled=false WHERE endpoint_id=$1',[f.endpointId]);assert.equal(await receiveSignedIngress(pool,input,cryptoEnv),null);await q(`UPDATE cf_webhook_ingress_binding SET enabled=true,valid_until=clock_timestamp()-interval '1 second' WHERE endpoint_id=$1`,[f.endpointId]);assert.equal(await receiveSignedIngress(pool,input,cryptoEnv),null);});
test('signed ingress refuses provider test events unknown kinds and outgoing inbound',async()=>{const f=await signedFixture();for(const event of [{...f.event,test:true},{...f.event,test:false},{...f.event,event:'post.published'},{...f.event,message:{...f.event.message,direction:'outgoing'}}])assert.equal(await receiveSignedIngress(pool,await signedInput(f,event),cryptoEnv),null);});
test('signed ingress cannot overwrite a duplicate event with changed payload',async()=>{const f=await signedFixture(),a=await receiveSignedIngress(pool,await signedInput(f),cryptoEnv);assert.ok(a);f.event.message.text='CHANGED';assert.equal(await receiveSignedIngress(pool,await signedInput(f),cryptoEnv),null);assert.equal((await q('SELECT payload FROM cf_inbound_job WHERE id=$1',[a.jobId])).rows[0].payload.message.text,'SYNTHETIC ONLY');});
test('signed ingress rechecks wall-clock expiry after mapping lock wait',async()=>{const f=await signedFixture(),input=await signedInput(f);await q(`UPDATE cf_webhook_ingress_binding SET valid_until=clock_timestamp()+interval '150 milliseconds' WHERE endpoint_id=$1`,[f.endpointId]);const lock=await pool.connect();await lock.query('BEGIN');await lock.query('SELECT 1 FROM cf_webhook_ingress_binding WHERE endpoint_id=$1 FOR UPDATE',[f.endpointId]);const call=receiveSignedIngress(pool,input,cryptoEnv);await delay(250);await lock.query('COMMIT');lock.release();assert.equal(await call,null);});
test('signed ingress durable receipts remain pending until a background reducer runs',async()=>{const f=await signedFixture();for(const kind of ['delivered','read','failed']){const event={...f.event,id:ws(),event:'message.'+kind};const r=await receiveSignedIngress(pool,await signedInput(f,event),cryptoEnv);assert.ok(r);assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[r.jobId])).rows[0].state,'received');}assert.equal((await q('SELECT count(*) FROM cf_unmatched_receipt WHERE workspace_id=$1',[f.workspaceId])).rows[0].count,'0');});
test('signed ingress rejects overlarge bytes and malformed endpoint without any job',async()=>{const f=await signedFixture(),input=await signedInput(f);for(const change of [{endpointId:'bad'},{raw:new Uint8Array(32769)}])assert.equal(await receiveSignedIngress(pool,{...input,...change},cryptoEnv),null);assert.equal((await q('SELECT count(*) FROM cf_inbound_job WHERE workspace_id=$1',[f.workspaceId])).rows[0].count,'0');});
async function normalFixture(){const f=await signedFixture();f.contactId=ws();f.event.message.platform='whatsapp';f.event.message.sender={id:'opaque-no-phone',businessScopedUserId:'synthetic-bsuid',phoneNumber:null};f.event.message.sentAt=new Date(Date.now()-25*3600000).toISOString();await q(`INSERT INTO cf_sender_identity(workspace_id,channel_id,provider,account_id,platform,identity_kind,identity_key,contact_id,evidence_ref,valid_until) VALUES($1,$2,'zernio',$3,'whatsapp','bsuid','synthetic-bsuid',$4,'SYNTHETIC',clock_timestamp()+interval '1 hour')`,[f.workspaceId,f.channelId,f.event.account.accountId,f.contactId]);return f;}
async function queuedNormal(f){const r=await receiveSignedIngress(pool,await signedInput(f),cryptoEnv);const j=await claimInbound(pool,f.workspaceId);assert.equal(j.id,r.jobId);return j;}
test('normalization persists registration channel and BSUID identity with no bot reply grant',async()=>{const f=await normalFixture(),j=await queuedNormal(f);assert.equal(j.ingress_endpoint_id,f.endpointId);assert.equal(j.ingress_channel_id,f.channelId);assert.equal(await normalizeInboundJob(pool,f.workspaceId,j.id,j.lease_token),true);const n=(await q('SELECT * FROM cf_normalized_inbound WHERE job_id=$1',[j.id])).rows[0];assert.equal(n.contact_id,f.contactId);assert.equal(n.bot_reply_allowed,false);assert.equal(n.processing_state,'held');assert.equal((await q('SELECT count(*) FROM cf_outbound_message WHERE workspace_id=$1',[f.workspaceId])).rows[0].count,'0');});
test('standby inbound pauses existing conversation without suppression or a reply',async()=>{const f=await normalFixture(),s={workspaceId:f.workspaceId,channelId:f.channelId,contactId:f.contactId};await active(s);f.event.metadata={standby:true};const j=await queuedNormal(f);assert.equal(await normalizeInboundJob(pool,f.workspaceId,j.id,j.lease_token),true);const c=(await q('SELECT * FROM cf_conversation_control WHERE workspace_id=$1',[f.workspaceId])).rows[0];assert.equal(c.state,'paused');assert.equal(c.suppressed,false);assert.equal(c.last_inbound_at,null);});
test('authenticated STOP suppresses global identity even in standby and completes atomically',async()=>{const f=await normalFixture();f.event.message.text=' STOP ';f.event.metadata={standby:true};const j=await queuedNormal(f);assert.equal(await normalizeInboundJob(pool,f.workspaceId,j.id,j.lease_token),true);assert.equal((await q('SELECT suppressed FROM cf_contact_suppression WHERE workspace_id=$1',[f.workspaceId])).rows[0].suppressed,true);assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[j.id])).rows[0].state,'completed');assert.equal(await normalizeInboundJob(pool,f.workspaceId,j.id,j.lease_token),false);assert.equal((await q('SELECT count(*) FROM cf_control_audit WHERE workspace_id=$1',[f.workspaceId])).rows[0].count,'1');});
test('old redelivery sentAt cannot reopen service window',async()=>{const f=await normalFixture(),s={workspaceId:f.workspaceId,channelId:f.channelId,contactId:f.contactId};await active(s);const j=await queuedNormal(f);await normalizeInboundJob(pool,f.workspaceId,j.id,j.lease_token);assert.equal((await q('SELECT last_inbound_at,inbound_evidence_ref FROM cf_conversation_control WHERE workspace_id=$1',[f.workspaceId])).rows[0].last_inbound_at,null);});
test('ingress remapping or credential rotation before processing rolls back normalized effects',async()=>{for(const change of ["channel_id='"+ws()+"'","encrypted_secret='rotated'"]){const f=await normalFixture(),j=await queuedNormal(f);await q('UPDATE cf_webhook_ingress_binding SET '+change+' WHERE endpoint_id=$1',[f.endpointId]);await assert.rejects(()=>normalizeInboundJob(pool,f.workspaceId,j.id,j.lease_token),/ingress_remapped/);assert.equal((await q('SELECT count(*) FROM cf_normalized_inbound WHERE job_id=$1',[j.id])).rows[0].count,'0');assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[j.id])).rows[0].state,'processing');}});
test('BSUID must not silently fall back to a phone identity mapping',async()=>{const f=await normalFixture();await q(`UPDATE cf_sender_identity SET identity_kind='phone',identity_key='+27610000000' WHERE workspace_id=$1`,[f.workspaceId]);f.event.message.sender.phoneNumber='+27610000000';const j=await queuedNormal(f);await assert.rejects(()=>normalizeInboundJob(pool,f.workspaceId,j.id,j.lease_token),/sender_identity_unresolved/);});
