test('normalization wrong tenant or stale lease cannot write effects',async()=>{const f=await normalFixture(),j=await queuedNormal(f);assert.equal(await normalizeInboundJob(pool,ws(),j.id,j.lease_token),false);assert.equal(await normalizeInboundJob(pool,f.workspaceId,j.id,ws()),false);assert.equal((await q('SELECT count(*) FROM cf_normalized_inbound WHERE job_id=$1',[j.id])).rows[0].count,'0');});
