for(const text of ['STOP ALL','  sToP aLl  '])for(const standby of [false,true])test('mapped opt-out '+JSON.stringify(text)+' standby='+standby,async()=>{const f=await normalFixture();f.event.message.text=text;f.event.metadata={standby};const j=await queuedNormal(f);assert.equal(await normalizeInboundJob(pool,f.workspaceId,j.id,j.lease_token),true);assert.equal((await q('SELECT suppressed FROM cf_contact_suppression WHERE workspace_id=$1',[f.workspaceId])).rows[0].suppressed,true);assert.equal((await q('SELECT stop FROM cf_normalized_inbound WHERE job_id=$1',[j.id])).rows[0].stop,true);});
