test('ingress abort while registration row locked rolls back and retry keeps same durable ID',async()=>{const f=await signedFixture(),input=await signedInput(f),controller=new AbortController();const lock=await pool.connect();await lock.query('BEGIN');await lock.query('SELECT 1 FROM cf_webhook_ingress_binding WHERE endpoint_id=$1 FOR UPDATE',[f.endpointId]);const call=receiveSignedIngress(pool,{...input,signal:controller.signal},cryptoEnv);await delay(30);controller.abort();await lock.query('COMMIT');lock.release();await assert.rejects(()=>call,/ingress_deadline/);assert.equal((await q('SELECT count(*) FROM cf_inbound_job WHERE workspace_id=$1',[f.workspaceId])).rows[0].count,'0');const a=await receiveSignedIngress(pool,input,cryptoEnv),b=await receiveSignedIngress(pool,input,cryptoEnv);assert.equal(a.jobId,b.jobId);});
test('abort during insertion before commit rolls back durable receipt',async()=>{const f=await signedFixture(),input=await signedInput(f),controller=new AbortController();await q(`CREATE FUNCTION delay_ingress_test() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM pg_sleep(0.12); RETURN NEW; END $$`);await q(`CREATE TRIGGER delay_ingress BEFORE INSERT ON cf_inbound_job FOR EACH ROW EXECUTE FUNCTION delay_ingress_test()`);try{const call=receiveSignedIngress(pool,{...input,signal:controller.signal},cryptoEnv);await delay(40);controller.abort();await assert.rejects(()=>call,/ingress_deadline/);assert.equal((await q('SELECT count(*) FROM cf_inbound_job WHERE workspace_id=$1',[f.workspaceId])).rows[0].count,'0');}finally{await q('DROP TRIGGER delay_ingress ON cf_inbound_job');await q('DROP FUNCTION delay_ingress_test()');}});
test('ingress DB lock wait bounded and connection usable after rollback',async()=>{const f=await signedFixture(),input=await signedInput(f);const lock=await pool.connect();await lock.query('BEGIN');await lock.query('SELECT 1 FROM cf_webhook_ingress_binding WHERE endpoint_id=$1 FOR UPDATE',[f.endpointId]);const start=Date.now();try{await assert.rejects(()=>receiveSignedIngress(pool,input,cryptoEnv),/lock timeout/);assert.ok(Date.now()-start<2000);}finally{await lock.query('ROLLBACK');lock.release();}assert.ok(await receiveSignedIngress(pool,input,cryptoEnv));});
test('late pool acquire rejection after abort is handled',async()=>{const f=await signedFixture(),input=await signedInput(f),controller=new AbortController();const fake={connect:()=>new Promise((_r,reject)=>setTimeout(()=>reject(Error('synthetic-acquire-failed')),30))};const call=receiveSignedIngress(fake,{...input,signal:controller.signal},cryptoEnv);controller.abort();assert.equal(await call,null);await delay(60);});
test('late acquired client is destroyed after total ingress abort',async()=>{const f=await signedFixture(),input=await signedInput(f),controller=new AbortController();let destroyed=false;const fake={connect:()=>new Promise(resolve=>setTimeout(()=>resolve({release:v=>{destroyed=v;}}),30))};const call=receiveSignedIngress(fake,{...input,signal:controller.signal},cryptoEnv);controller.abort();assert.equal(await call,null);await delay(60);assert.equal(destroyed,true);});
async function durableReceiptFixture(){const f=await signedFixture();f.event.event='message.delivered';
// Build outbound under ingress tenant, using existing tested consuming fence.
 const s={workspaceId:f.workspaceId,contactId:ws(),channelId:f.channelId};await active(s);const id=await message(s);await q(`UPDATE cf_outbound_message SET provider='zernio',account_id=$2 WHERE id=$1`,[id,f.event.account.accountId]);const r=await reserveDispatch(pool,s,id,valid(),budget()),token=await claimProviderStart(pool,s,id,r.attemptId);const settlement={workspaceId:s.workspaceId,messageId:id,attemptId:r.attemptId,startToken:token,provider:'zernio',accountId:f.event.account.accountId,outcome:'accepted',providerMessageId:f.event.message.id};return{f,s,id,settlement};}
test('durable receipt processing reconciles and completes in one fenced transaction',async()=>{const x=await durableReceiptFixture();await settleProviderStart(pool,x.settlement);const j=await queuedNormal(x.f);assert.equal(await processReceiptJob(pool,x.f.workspaceId,j.id,j.lease_token),'reconciled');assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'delivered');assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[j.id])).rows[0].state,'completed');assert.equal(await processReceiptJob(pool,x.f.workspaceId,j.id,j.lease_token),'stale');});
test('early durable receipt stays retry_wait and reconciles after response with no resend',async()=>{const x=await durableReceiptFixture(),j=await queuedNormal(x.f);assert.equal(await processReceiptJob(pool,x.f.workspaceId,j.id,j.lease_token),'retryable_unmatched');assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[j.id])).rows[0].state,'retry_wait');assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'dispatching');await settleProviderStart(pool,x.settlement);await q('UPDATE cf_inbound_job SET available_at=clock_timestamp() WHERE id=$1',[j.id]);const next=await claimInbound(pool,x.f.workspaceId);assert.equal(await processReceiptJob(pool,x.f.workspaceId,next.id,next.lease_token),'duplicate');assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'delivered');});
test('receipt processing wrong tenant and stale lease cannot settle or complete',async()=>{const x=await durableReceiptFixture();await settleProviderStart(pool,x.settlement);const j=await queuedNormal(x.f);assert.equal(await processReceiptJob(pool,ws(),j.id,j.lease_token),'stale');assert.equal(await processReceiptJob(pool,x.f.workspaceId,j.id,ws()),'stale');assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'provider_accepted');});
test('receipt remapping rolls back without advancing receipt or message',async()=>{const x=await durableReceiptFixture();await settleProviderStart(pool,x.settlement);const j=await queuedNormal(x.f);await q('UPDATE cf_webhook_ingress_binding SET channel_id=$2 WHERE endpoint_id=$1',[x.f.endpointId,ws()]);await assert.rejects(()=>processReceiptJob(pool,x.f.workspaceId,j.id,j.lease_token),/ingress_remapped/);assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'provider_accepted');});
test('receipt final lease expiry rolls back message effects and unmatched inbox',async()=>{const x=await durableReceiptFixture();await settleProviderStart(pool,x.settlement);const j=await queuedNormal(x.f);await q(`UPDATE cf_inbound_job SET lease_until=clock_timestamp()+interval '150 milliseconds' WHERE id=$1`,[j.id]);const lock=await pool.connect();await lock.query('BEGIN');await lock.query('SELECT 1 FROM cf_outbound_message WHERE id=$1 FOR UPDATE',[x.id]);const run=processReceiptJob(pool,x.f.workspaceId,j.id,j.lease_token);await delay(250);await lock.query('COMMIT');lock.release();assert.equal(await run,'stale');assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'provider_accepted');assert.equal((await q('SELECT count(*) FROM cf_unmatched_receipt WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].count,'0');});
test('durable receipt registered channelA cannot advance outbound channelB',async()=>{const x=await durableReceiptFixture();await settleProviderStart(pool,x.settlement);const other=ws();await q(`INSERT INTO cf_conversation_control(workspace_id,contact_id,channel_id) VALUES($1,$2,$3)`,[x.s.workspaceId,x.s.contactId,other]);await q('UPDATE cf_outbound_message SET channel_id=$2 WHERE id=$1',[x.id,other]);const j=await queuedNormal(x.f);assert.equal(await processReceiptJob(pool,x.f.workspaceId,j.id,j.lease_token),'retryable_unmatched');assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'provider_accepted');assert.equal((await q('SELECT state FROM cf_unmatched_receipt WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].state,'held');});
test('early channelA receipt cannot advance later channelB settlement',async()=>{const x=await durableReceiptFixture(),j=await queuedNormal(x.f);assert.equal(await processReceiptJob(pool,x.f.workspaceId,j.id,j.lease_token),'retryable_unmatched');const other=ws();await q(`INSERT INTO cf_conversation_control(workspace_id,contact_id,channel_id) VALUES($1,$2,$3)`,[x.s.workspaceId,x.s.contactId,other]);await q('UPDATE cf_outbound_message SET channel_id=$2 WHERE id=$1',[x.id,other]);assert.equal(await settleProviderStart(pool,x.settlement),true);assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'provider_accepted');assert.equal((await q('SELECT state FROM cf_unmatched_receipt WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].state,'held');});
