test('safety scan finds tenant deadletters without replay or message text disclosure',async()=>{const w=ws(),id=await inbound(w);await q(`UPDATE cf_inbound_job SET state='dead',last_error_code='attempts_exhausted' WHERE id=$1`,[id]);assert.equal(await scanSafetyHolds(pool,w),1);const a=(await q(`SELECT * FROM cf_safety_alert WHERE workspace_id=$1 AND kind='dead_inbound'`,[w])).rows[0];assert.equal(a.open,true);assert.equal(a.affected_count,'1');assert.equal(JSON.stringify(a).includes('payload'),false);assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[id])).rows[0].state,'dead');});
test('safety scan concurrent identical observations keep stable version and firstseen',async()=>{const w=ws(),id=await inbound(w);await q(`UPDATE cf_inbound_job SET state='dead' WHERE id=$1`,[id]);await scanSafetyHolds(pool,w);const first=(await q(`SELECT version,first_seen_at FROM cf_safety_alert WHERE workspace_id=$1 AND kind='dead_inbound'`,[w])).rows[0];await Promise.all(Array.from({length:5},()=>scanSafetyHolds(pool,w)));const after=(await q(`SELECT version,first_seen_at FROM cf_safety_alert WHERE workspace_id=$1 AND kind='dead_inbound'`,[w])).rows[0];assert.deepEqual(after,first);});
test('safety scan cannot include another tenant and resolves only after sourcechange',async()=>{const a=ws(),b=ws(),id=await inbound(a);await q(`UPDATE cf_inbound_job SET state='dead' WHERE id=$1`,[id]);assert.equal(await scanSafetyHolds(pool,b),0);await scanSafetyHolds(pool,a);await q(`UPDATE cf_inbound_job SET state='received' WHERE id=$1`,[id]);assert.equal(await scanSafetyHolds(pool,a),0);const r=(await q(`SELECT open,resolved_at,version FROM cf_safety_alert WHERE workspace_id=$1 AND kind='dead_inbound'`,[a])).rows[0];assert.equal(r.open,false);assert.ok(r.resolved_at);assert.equal(r.version,'2');});
test('safety scan ages unmatched receipts and unknown sends without resending',async()=>{const x=await started();await reduceDeliveryReceipt(pool,receipt(x));await settleProviderStart(pool,{...x.input,outcome:'unknown'});await q(`UPDATE cf_unmatched_receipt SET created_at=clock_timestamp()-interval '6 minutes' WHERE workspace_id=$1`,[x.s.workspaceId]);assert.equal(await scanSafetyHolds(pool,x.s.workspaceId),2);assert.equal((await q('SELECT state FROM cf_outbound_message WHERE id=$1',[x.id])).rows[0].state,'unknown');});
async function alertFixture(){const w=ws(),id=await inbound(w);await q(`UPDATE cf_inbound_job SET state='dead' WHERE id=$1`,[id]);await scanSafetyHolds(pool,w);return{w,id};}
test('internal alert enqueue idempotent per exact source version with redacted payload',async()=>{const {w}=await alertFixture();const r=await Promise.all(Array.from({length:10},()=>queueSafetyAlerts(pool,w)));assert.equal(r.reduce((a,b)=>a+b),1);const d=(await q('SELECT * FROM cf_safety_alert_delivery WHERE workspace_id=$1',[w])).rows[0];assert.deepEqual(Object.keys(d.payload).sort(),['count','kind','oldestAt','version']);assert.equal(d.state,'queued');assert.equal(d.delivered_at,null);});
