for(const mode of ['clear','version'])test('alert source '+mode+' interleaving serialized before claim',async()=>{const {w}=await alertFixture();await queueSafetyAlerts(pool,w);const barrier=await pool.connect();await barrier.query('BEGIN');await barrier.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))',['safety-alert:'+w]);const claim=claimSafetyAlert(pool,w);await delay(30);await barrier.query(mode==='clear'?`UPDATE cf_safety_alert SET open=false,version=version+1 WHERE workspace_id=$1 AND kind='dead_inbound'`:`UPDATE cf_safety_alert SET version=version+1,affected_count=affected_count+1 WHERE workspace_id=$1 AND kind='dead_inbound'`,[w]);await barrier.query('COMMIT');barrier.release();assert.equal(await claim,null);assert.equal((await q('SELECT state FROM cf_safety_alert_delivery WHERE workspace_id=$1',[w])).rows[0].state,'cancelled');});
async function handoverFixture(owner='other'){const f=await signedFixture();f.contactId=ws();const conversationId=ws();f.event={...f.event,event:'conversation.control_changed',conversation:{id:conversationId},control:{owner,previousOwner:'app',metadata:'UNTRUSTED-NOTE'},changedAt:new Date().toISOString()};delete f.event.message;await q(`INSERT INTO cf_provider_conversation_identity(workspace_id,channel_id,provider,account_id,conversation_id,contact_id,evidence_ref,valid_until) VALUES($1,$2,'zernio',$3,$4,$5,'SYNTHETIC',clock_timestamp()+interval '1 hour')`,[f.workspaceId,f.channelId,f.event.account.accountId,conversationId,f.contactId]);await active({workspaceId:f.workspaceId,channelId:f.channelId,contactId:f.contactId});return f;}
for(const owner of ['app','ai_agent','other'])test('handover '+owner+' only pauses, never resumes or schedules a reply',async()=>{const f=await handoverFixture(owner),j=await queuedNormal(f);assert.equal(await applyHandoverJob(pool,f.workspaceId,j.id,j.lease_token),true);const c=(await q('SELECT state,suppressed FROM cf_conversation_control WHERE workspace_id=$1',[f.workspaceId])).rows[0];assert.equal(c.state,'paused');assert.equal(c.suppressed,false);assert.equal((await q('SELECT count(*) FROM cf_outbound_message WHERE workspace_id=$1',[f.workspaceId])).rows[0].count,'0');assert.equal(await applyHandoverJob(pool,f.workspaceId,j.id,j.lease_token),false);});
test('handover app ownership cannot clear STOP suppression',async()=>{const f=await handoverFixture('app');await pauseConversation(pool,{workspaceId:f.workspaceId,contactId:f.contactId,channelId:f.channelId},'stop',true);const j=await queuedNormal(f);await applyHandoverJob(pool,f.workspaceId,j.id,j.lease_token);assert.equal((await q('SELECT suppressed FROM cf_contact_suppression WHERE workspace_id=$1',[f.workspaceId])).rows[0].suppressed,true);});
test('handover unknown conversation or expired identity holds without effects',async()=>{for(const mode of ['unknown','expired']){const f=await handoverFixture();if(mode==='unknown')f.event.conversation.id=ws();else await q(`UPDATE cf_provider_conversation_identity SET valid_until=clock_timestamp()-interval '1 second' WHERE workspace_id=$1`,[f.workspaceId]);const j=await queuedNormal(f);await assert.rejects(()=>applyHandoverJob(pool,f.workspaceId,j.id,j.lease_token),/conversation_identity_unresolved|inbound_evidence_expired/);assert.equal((await q('SELECT state FROM cf_conversation_control WHERE workspace_id=$1',[f.workspaceId])).rows[0].state,'active');}});
