async function recoveryFixture(){const f=await normalFixture(),j=await queuedNormal(f);await q(`UPDATE cf_inbound_job SET state='dead',attempts=5,last_error_code='sender_identity_unresolved',lease_token=NULL,lease_until=NULL WHERE id=$1`,[j.id]);const a=ws(),payload=(await q('SELECT payload FROM cf_inbound_job WHERE id=$1',[j.id])).rows[0].payload;await q(`INSERT INTO cf_inbound_recovery_approval(id,workspace_id,job_id,actor_id,evidence_ref,expected_generation,expected_attempts,expected_error,payload_sha256,ingress_fingerprint,valid_until) VALUES($1,$2,$3,$4,'SYNTHETIC-NOT-REAL-AUTHORITY',0,5,'sender_identity_unresolved',$5,$6,clock_timestamp()+interval '1 hour')`,[a,f.workspaceId,j.id,actor,await recoveryPayloadHash(payload),j.ingress_fingerprint]);return{f,j,a};}
test('dead inbound recovery requires exact one-use approval and preserves original job/audit',async()=>{const {f,j,a}=await recoveryFixture();assert.equal(await recoverDeadInbound(pool,f.workspaceId,j.id,a),true);assert.equal(await recoverDeadInbound(pool,f.workspaceId,j.id,a),false);const n=await claimInbound(pool,f.workspaceId);assert.equal(n.id,j.id);await normalizeInboundJob(pool,f.workspaceId,n.id,n.lease_token);assert.equal((await q('SELECT prior_attempts FROM cf_inbound_recovery_audit WHERE approval_id=$1',[a])).rows[0].prior_attempts,5);assert.equal((await q('SELECT bot_reply_allowed FROM cf_normalized_inbound WHERE job_id=$1',[j.id])).rows[0].bot_reply_allowed,false);});
test('recovery concurrency consumes approval once',async()=>{const {f,j,a}=await recoveryFixture();assert.equal((await Promise.all([recoverDeadInbound(pool,f.workspaceId,j.id,a),recoverDeadInbound(pool,f.workspaceId,j.id,a)])).filter(Boolean).length,1);});
for(const mode of ['wrongtenant','missing','expired','hash','attempts','error','fingerprint','binding','processing','completed','effect'])test('recovery fails closed '+mode,async()=>{const {f,j,a}=await recoveryFixture();if(mode==='expired')await q(`UPDATE cf_inbound_recovery_approval SET valid_until=clock_timestamp()-interval '1 second' WHERE id=$1`,[a]);if(mode==='hash')await q(`UPDATE cf_inbound_job SET payload=payload||'{"tampered":true}'::jsonb WHERE id=$1`,[j.id]);if(mode==='attempts')await q('UPDATE cf_inbound_job SET attempts=6 WHERE id=$1',[j.id]);if(mode==='error')await q("UPDATE cf_inbound_job SET last_error_code='other_error' WHERE id=$1",[j.id]);if(mode==='fingerprint')await q("UPDATE cf_inbound_recovery_approval SET ingress_fingerprint='other' WHERE id=$1",[a]);if(mode==='binding')await q('UPDATE cf_webhook_ingress_binding SET enabled=false WHERE endpoint_id=$1',[f.endpointId]);if(mode==='processing')await q("UPDATE cf_inbound_job SET state='processing',lease_token=$2,lease_until=clock_timestamp()+interval '30 seconds' WHERE id=$1",[j.id,ws()]);if(mode==='completed')await q("UPDATE cf_inbound_job SET state='completed' WHERE id=$1",[j.id]);if(mode==='effect')await q(`INSERT INTO cf_normalized_inbound(job_id,workspace_id,channel_id,contact_id,provider_message_id,provider_conversation_id,standby,stop) VALUES($1,$2,$3,$4,'m','c',false,false)`,[j.id,f.workspaceId,f.channelId,f.contactId]);assert.equal(await recoverDeadInbound(pool,mode==='wrongtenant'?ws():f.workspaceId,j.id,mode==='missing'?ws():a),false);assert.equal((await q('SELECT count(*) FROM cf_inbound_recovery_audit WHERE approval_id=$1',[a])).rows[0].count,'0');});

test('preissued approval from old recovery generation cannot restart later failure',async()=>{const {f,j,a}=await recoveryFixture(),b=ws();await q(`INSERT INTO cf_inbound_recovery_approval SELECT $2,workspace_id,job_id,actor_id,evidence_ref,expected_generation,expected_attempts,expected_error,payload_sha256,ingress_fingerprint,valid_until,consumed_at FROM cf_inbound_recovery_approval WHERE id=$1`,[a,b]);assert.equal(await recoverDeadInbound(pool,f.workspaceId,j.id,a),true);await q(`UPDATE cf_inbound_job SET state='dead',attempts=5,last_error_code='sender_identity_unresolved' WHERE id=$1`,[j.id]);assert.equal(await recoverDeadInbound(pool,f.workspaceId,j.id,b),false);});

async function ownerRecoveryFixture(){const x=await recoveryFixture();await q('DELETE FROM cf_inbound_recovery_approval WHERE id=$1',[x.a]);const token='a'.repeat(32)+ws().replaceAll('-',''),user=ws(),org=ws();await q('INSERT INTO accounts_user VALUES($1,true)',[user]);await q('INSERT INTO organizations_organization VALUES($1,NULL)',[org]);await q('INSERT INTO workspaces_workspace VALUES($1,$2,false)',[x.f.workspaceId,org]);await q("INSERT INTO members_workspace_membership VALUES($1,$2,$3,'owner',NULL)",[ws(),user,x.f.workspaceId]);const rawHash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token))),n=>n.toString(16).padStart(2,'0')).join('');await q("INSERT INTO cf_sessions VALUES($1,$2,clock_timestamp()+interval '1 hour')",[rawHash,user]);const job=(await q('SELECT * FROM cf_inbound_job WHERE id=$1',[x.j.id])).rows[0];const choice={workspaceId:x.f.workspaceId,jobId:x.j.id,jobFingerprint:await ingressFingerprint(job)};const request=(headers={})=>new Request('https://synthetic.invalid/recovery',{method:'POST',headers:{origin:'https://synthetic.invalid',cookie:'cf_session='+token,...headers}});return{...x,token,user,org,choice,request};}
test('authenticated exact workspace owner writes bounded recovery approval, no replay effects',async()=>{const x=await ownerRecoveryFixture(),id=await approveInboundRecovery(pool,x.request(),x.choice,'https://synthetic.invalid');assert.ok(id);const a=(await q('SELECT * FROM cf_inbound_recovery_approval WHERE id=$1',[id])).rows[0];assert.equal(a.actor_id,x.user);assert.equal(a.expected_generation,0);assert.equal(a.consumed_at,null);assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[x.j.id])).rows[0].state,'dead');assert.equal(await recoverDeadInbound(pool,x.f.workspaceId,x.j.id,id),true);});
for(const mode of ['origin','cookie','role','customrole','inactive','archived','deleted','expired','crossworkspace','snapshot','binding'])test('owner recovery approval denies '+mode,async()=>{const x=await ownerRecoveryFixture();if(mode==='role')await q("UPDATE members_workspace_membership SET workspace_role='manager' WHERE user_id=$1",[x.user]);if(mode==='customrole')await q('UPDATE members_workspace_membership SET custom_role_id=$2 WHERE user_id=$1',[x.user,ws()]);if(mode==='inactive')await q('UPDATE accounts_user SET is_active=false WHERE id=$1',[x.user]);if(mode==='archived')await q('UPDATE workspaces_workspace SET is_archived=true WHERE id=$1',[x.f.workspaceId]);if(mode==='deleted')await q('UPDATE organizations_organization SET deleted_at=clock_timestamp() WHERE id=$1',[x.org]);if(mode==='expired')await q("UPDATE cf_sessions SET expires_at=clock_timestamp()-interval '1 second' WHERE user_id=$1",[x.user]);if(mode==='crossworkspace')x.choice.workspaceId=ws();if(mode==='snapshot')x.choice.jobFingerprint='0'.repeat(64);if(mode==='binding')await q('UPDATE cf_webhook_ingress_binding SET enabled=false WHERE endpoint_id=$1',[x.f.endpointId]);const req=x.request(mode==='origin'?{origin:'https://evil.invalid'}:mode==='cookie'?{cookie:'cf_session='+'0'.repeat(64)}:{});assert.equal(await approveInboundRecovery(pool,req,x.choice,'https://synthetic.invalid'),null);assert.equal((await q('SELECT count(*) FROM cf_inbound_recovery_approval WHERE job_id=$1',[x.j.id])).rows[0].count,'0');});
test('owner recovery approval rejects session expiring during job lock wait',async()=>{const x=await ownerRecoveryFixture();await q(`UPDATE cf_sessions SET expires_at=clock_timestamp()+interval '120 milliseconds' WHERE user_id=$1`,[x.user]);const b=await pool.connect();await b.query('BEGIN');await b.query('SELECT id FROM cf_inbound_job WHERE id=$1 FOR UPDATE',[x.j.id]);const call=approveInboundRecovery(pool,x.request(),x.choice,'https://synthetic.invalid');await delay(180);await b.query('COMMIT');b.release();assert.equal(await call,null);});
