async function identityWriterFixture(){const x=await ownerRecoveryFixture();await q('DELETE FROM cf_sender_identity WHERE workspace_id=$1',[x.f.workspaceId]);await q('INSERT INTO receptionist_contact VALUES($1,$2,false,false)',[x.f.contactId,x.f.workspaceId]);x.choice.contactId=x.f.contactId;return x;}
test('owner mapping derives signed BSUID and conversation, pauses without consent/window/retry grants',async()=>{const x=await identityWriterFixture();assert.equal(await confirmInboundIdentity(pool,x.request(),x.choice,'https://synthetic.invalid'),true);const sender=(await q('SELECT * FROM cf_sender_identity WHERE workspace_id=$1',[x.f.workspaceId])).rows[0];assert.equal(sender.contact_id,x.f.contactId);assert.equal(sender.identity_kind,'bsuid');const c=(await q('SELECT * FROM cf_conversation_control WHERE workspace_id=$1',[x.f.workspaceId])).rows[0];assert.equal(c.state,'paused');assert.equal(c.last_inbound_at,null);assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[x.j.id])).rows[0].state,'dead');assert.equal((await q('SELECT actor_id FROM cf_identity_mapping_audit WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].actor_id,x.user);});
test('identity mapping preserves legacy opt-out globally',async()=>{const x=await identityWriterFixture();await q('UPDATE receptionist_contact SET opted_out=true WHERE id=$1',[x.f.contactId]);assert.equal(await confirmInboundIdentity(pool,x.request(),x.choice,'https://synthetic.invalid'),true);assert.equal((await q('SELECT suppressed FROM cf_contact_suppression WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].suppressed,true);});
test('concurrent mapping confirmations cannot duplicate or remap',async()=>{const x=await identityWriterFixture();assert.equal((await Promise.all([confirmInboundIdentity(pool,x.request(),x.choice,'https://synthetic.invalid'),confirmInboundIdentity(pool,x.request(),x.choice,'https://synthetic.invalid')])).filter(Boolean).length,1);});
for(const mode of ['contacttenant','missingcontact','snapshot','role','origin','existing_sender','existing_conversation','expired'])test('identity writer rejects '+mode,async()=>{const x=await identityWriterFixture();if(mode==='contacttenant')await q('UPDATE receptionist_contact SET workspace_id=$2 WHERE id=$1',[x.f.contactId,ws()]);if(mode==='missingcontact')x.choice.contactId=ws();if(mode==='snapshot')x.choice.jobFingerprint='0'.repeat(64);if(mode==='role')await q("UPDATE members_workspace_membership SET workspace_role='manager' WHERE user_id=$1",[x.user]);if(mode==='expired')await q("UPDATE cf_sessions SET expires_at=clock_timestamp()-interval '1 second' WHERE user_id=$1",[x.user]);if(mode==='existing_sender')await q(`INSERT INTO cf_sender_identity(workspace_id,channel_id,provider,account_id,platform,identity_kind,identity_key,contact_id,evidence_ref,valid_until) VALUES($1,$2,'zernio',$3,'whatsapp','bsuid',$4,$5,'other',clock_timestamp()-interval '1 second')`,[x.f.workspaceId,x.f.channelId,x.f.event.account.accountId,x.f.event.message.sender.businessScopedUserId,ws()]);if(mode==='existing_conversation')await q(`INSERT INTO cf_provider_conversation_identity VALUES($1,$2,'zernio',$3,$4,$5,'other',clock_timestamp()+interval '1 hour')`,[x.f.workspaceId,x.f.channelId,x.f.event.account.accountId,x.f.event.message.conversationId,ws()]);assert.equal(await confirmInboundIdentity(pool,x.request(mode==='origin'?{origin:'https://evil.invalid'}:{}),x.choice,'https://synthetic.invalid'),false);assert.equal((await q('SELECT count(*) FROM cf_identity_mapping_audit WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].count,'0');});
async function confirmRecoverJourney(mode){const x=await identityWriterFixture();if(mode==='stop'||mode==='standby'){const payload=(await q('SELECT payload FROM cf_inbound_job WHERE id=$1',[x.j.id])).rows[0].payload;if(mode==='stop')payload.message.text=' STOP ALL ';else payload.metadata={standby:true};await q('UPDATE cf_inbound_job SET payload=$2 WHERE id=$1',[x.j.id,JSON.stringify(payload)]);x.choice.jobFingerprint=await ingressFingerprint((await q('SELECT * FROM cf_inbound_job WHERE id=$1',[x.j.id])).rows[0]);}assert.equal(await confirmInboundIdentity(pool,x.request(),x.choice,'https://synthetic.invalid'),true);const approval=await approveInboundRecovery(pool,x.request(),x.choice,'https://synthetic.invalid');assert.ok(approval);assert.equal(await recoverDeadInbound(pool,x.f.workspaceId,x.j.id,approval),true);const j=await claimInbound(pool,x.f.workspaceId);assert.equal(await normalizeInboundJob(pool,x.f.workspaceId,j.id,j.lease_token),true);return x;}
for(const mode of ['stop','standby','held'])test('integrated owner mapping approval recovery normalization '+mode,async()=>{const x=await confirmRecoverJourney(mode);const n=(await q('SELECT * FROM cf_normalized_inbound WHERE job_id=$1',[x.j.id])).rows[0];assert.equal(n.stop,mode==='stop');assert.equal(n.standby,mode==='standby');assert.equal(n.bot_reply_allowed,false);assert.equal(n.processing_state,'held');assert.equal((await q('SELECT state FROM cf_conversation_control WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].state,'paused');assert.equal((await q('SELECT count(*) FROM cf_outbound_message WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].count,'0');assert.equal((await q('SELECT count(*) FROM cf_identity_mapping_audit WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].count,'1');assert.equal((await q('SELECT count(*) FROM cf_inbound_recovery_audit WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].count,'1');});
test('integrated STOP then signed app handback cannot reopen or clear suppression',async()=>{const x=await confirmRecoverJourney('stop');const e={id:ws(),event:'conversation.control_changed',account:x.f.event.account,conversation:{id:x.f.event.message.conversationId},control:{owner:'app',previousOwner:'other'},changedAt:new Date(0).toISOString(),timestamp:new Date().toISOString()};const r=await receiveSignedIngress(pool,await signedInput(x.f,e),cryptoEnv);assert.ok(r);const j=await claimInbound(pool,x.f.workspaceId);assert.equal(await applyHandoverJob(pool,x.f.workspaceId,j.id,j.lease_token),true);assert.equal((await q('SELECT suppressed FROM cf_contact_suppression WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].suppressed,true);assert.equal((await q('SELECT state FROM cf_conversation_control WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].state,'paused');});
test('integrated mapping cannot make expired owner session a recovery approval',async()=>{const x=await identityWriterFixture();assert.equal(await confirmInboundIdentity(pool,x.request(),x.choice,'https://synthetic.invalid'),true);await q(`UPDATE cf_sessions SET expires_at=clock_timestamp()-interval '1 second' WHERE user_id=$1`,[x.user]);assert.equal(await approveInboundRecovery(pool,x.request(),x.choice,'https://synthetic.invalid'),null);assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[x.j.id])).rows[0].state,'dead');});
test('synthetic 120 tenants and 100 concurrent owner recovery sessions stay scoped',async()=>{const start=performance.now(),fixtures=[];for(let i=0;i<120;i++)fixtures.push(await identityWriterFixture());const results=await Promise.all(fixtures.slice(0,100).map(async x=>{assert.equal(await confirmInboundIdentity(pool,x.request(),x.choice,'https://synthetic.invalid'),true);const approval=await approveInboundRecovery(pool,x.request(),x.choice,'https://synthetic.invalid');assert.ok(approval);assert.equal(await recoverDeadInbound(pool,x.f.workspaceId,x.j.id,approval),true);const j=await claimInbound(pool,x.f.workspaceId);assert.equal(await normalizeInboundJob(pool,x.f.workspaceId,j.id,j.lease_token),true);const n=(await q('SELECT * FROM cf_normalized_inbound WHERE job_id=$1',[j.id])).rows[0];assert.equal(n.contact_id,x.f.contactId);assert.equal(n.workspace_id,x.f.workspaceId);assert.equal(n.bot_reply_allowed,false);return true;}));assert.equal(results.length,100);for(const x of fixtures.slice(100)){assert.equal((await q('SELECT state FROM cf_inbound_job WHERE id=$1',[x.j.id])).rows[0].state,'dead');assert.equal((await q('SELECT count(*) FROM cf_identity_mapping_audit WHERE workspace_id=$1',[x.f.workspaceId])).rows[0].count,'0');}console.log('SYNTHETIC_DB_JOURNEY_120_TENANTS_100_CONCURRENT_MS',Math.round(performance.now()-start));});
